var st={scale:1,tx:16,ty:16,dragging:false,startX:0,startY:0};viewportState[vpId]={state:st,vp:vp,svg:svg};
st.apply=function(){svg.style.transform='translate('+st.tx+'px,'+st.ty+'px) scale('+st.scale+')';var l=vp.parentElement&&vp.parentElement.querySelector('[data-zoom-label]');if(l)l.textContent=Math.round(st.scale*100)+'%'};
if(!fitToView(vpId))st.apply();
vp.addEventListener('wheel',function(ev){ev.preventDefault();var r=vp.getBoundingClientRect(),mx=ev.clientX-r.left,my=ev.clientY-r.top,ns=Math.min(2.6,Math.max(0.35,st.scale*(ev.deltaY<0?1.12:0.89)));st.tx=mx-(mx-st.tx)*(ns/st.scale);st.ty=my-(my-st.ty)*(ns/st.scale);st.scale=ns;st.apply()},{passive:false});
vp.addEventListener('pointerdown',function(ev){if(ev.target&&ev.target.closest&&ev.target.closest('.pf-node'))return;st.dragging=true;st.startX=ev.clientX-st.tx;st.startY=ev.clientY-st.ty;vp.classList.add('is-dragging')});
